parameters.jsCode:
const response = $json.choices[0].message.content;
let data = {};
let isValid = false;
let errorReason = "";

try {
  // Strip markdown backticks if the model ignored instructions
  const cleanJson = response.replace(/```json|```/g, "").trim();
  data = JSON.parse(cleanJson);

  // Validate required fields
  const hasFound = typeof data.found === 'boolean';
  const hasEmail = typeof data.email === 'string' || data.email === null;
  const hasDesc = typeof data.description === 'string';

  if (hasFound && hasEmail && hasDesc) {
    isValid = true;
  } else {
    errorReason = "JSON missing required fields or wrong types";
  }
} catch (e) {
  errorReason = "Invalid JSON format: " + e.message;
}

return {
  isValid,
  errorReason,
  found: data.found || false,
  email: data.email || null,
  description: data.description || "No data",
  raw: response
};

