// 1. Map the data to a flat structure
const results = $input.all().map(item => {
  // Extract the AI content from the previous node
  // Using optional chaining to prevent errors if content is missing
  const aiContent = item.json.message?.content || {};

  return {
    json: {
      id: aiContent.id,
      title: item.json.title,
      companyName: item.json.companyName,
      descriptionText: item.json.descriptionText,
      // This must match the key you use in the Google Sheets node mapping
      resume_match_score: aiContent.resume_match_score || 0,
      locationType: aiContent.locationType || 'Unknown'
    }
  };
});

// 2. Sort Descending by the match score
results.sort((a, b) => b.json.resume_match_score - a.json.resume_match_score);

// 3. Assign Token Rules & Rank
return results.map((item, index) => {
  let tokens = 15;
  let rank = index + 1;

  // Top rank gets 100, top 3 get 75, others get 15
  if (rank === 1) tokens = 100;
  else if (rank === 2 || rank === 3) tokens = 75;

  item.json.max_tokens = tokens;
  item.json.rank = rank;

  return item;
});

